// Example: Displaying a list of items with a total
function ShoppingCart({ items }) {
  const total = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

  return (
    <div>
      <h2>Shopping Cart</h2>
      {items.map(item => (
        <div key={item.id}>
          <span>{item.name}</span>
          <span>Quantity: {item.quantity}</span>
          <span>Price: ${item.price}</span>
        </div>
      ))}
      <h3>Total: ${total}</h3>
    </div>
  );
}

